SELECT

FROM bt_prompt_debug_log
WHERE deleted_at = 0

  AND prompt_id = #{promptId,jdbcType=BIGINT}


  AND debugged_by = #{userId,jdbcType=VARCHAR}


  AND started_at <= #{startBefore,jdbcType=BIGINT}


  AND ended_at >= #{startAfter,jdbcType=BIGINT}


  AND debug_id IN

    #{debugId,jdbcType=BIGINT}



  AND debug_step = #{debugStep,jdbcType=INTEGER}

ORDER BY started_at DESC
